'use strict';

const fs = require('fs');
const path = require('path');

/**
 * Load dialects from the shipped MAVLink XML seed (`seed/mavlink`).
 *
 * The seed is generated by `scripts/generate-seed.js`: pinned upstream commit,
 * full `message_definitions/v1.0` XML set, real `<include>` walks, and a
 * precompiled {@link DialectBundle} JSON per selectable root. Runtime just
 * reads those artifacts — no `mavlink-mappings`, no hand-maintained include
 * chains, no `.d.ts` archaeology. A later catalog update overlays newer XML
 * under the Node-RED userDir; until then the seed is the offline authority.
 */

const SEED_ROOT = path.join(__dirname, '..', '..', 'seed', 'mavlink');

/** @type {Map<string, import('./index').DialectBundle>} */
const cache = new Map();

/** @type {string[]|null} */
let dialectNames = null;

/**
 * Absolute path to the shipped seed root (`seed/mavlink`).
 *
 * @returns {string}
 */
function seedRoot() {
  return SEED_ROOT;
}

/**
 * @returns {object}
 */
function readManifest() {
  const p = path.join(SEED_ROOT, 'manifest.json');
  if (!fs.existsSync(p)) {
    throw new Error(
      `MAVLink dialect seed missing at ${p}. Run: node scripts/generate-seed.js`
    );
  }
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

/**
 * Selectable dialect names from the seed manifest (lowercase keys).
 *
 * @returns {string[]}
 */
function knownDialects() {
  if (!dialectNames) {
    const manifest = readManifest();
    dialectNames = (manifest.dialects || []).map((d) => d.name).sort();
  }
  return dialectNames.slice();
}

/**
 * Load a seeded dialect as a {@link DialectBundle}. Memoized. Unknown names
 * fail loud naming the available set — no silent fallback to `common`.
 *
 * @param {string} name  dialect key (e.g. `ardupilotmega`, `icarous`)
 * @returns {import('./index').DialectBundle}
 */
function loadBundled(name) {
  const key = String(name || '').toLowerCase();
  if (cache.has(key)) {
    return cache.get(key);
  }
  const file = path.join(SEED_ROOT, 'bundles', `${key}.json`);
  if (!fs.existsSync(file)) {
    throw new Error(
      `Unknown bundled dialect '${name}'. Available: ${knownDialects().join(', ')}.`
    );
  }
  const bundle = JSON.parse(fs.readFileSync(file, 'utf8'));
  cache.set(key, bundle);
  return bundle;
}

module.exports = { knownDialects, loadBundled, seedRoot, readManifest };
